import{X as e,Y as t,ct as n,t as r}from"./chunks/framework.CaFWb3SA.js";var i=JSON.parse(`{"title":"ERB 的表达式","description":"","frontmatter":{},"headers":[],"relativePath":"reference/ERB_Expressions.md","filePath":"reference/ERB_Expressions.md"}`),a={name:`reference/ERB_Expressions.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="erb-的表达式" tabindex="-1">ERB 的表达式 <a class="header-anchor" href="#erb-的表达式" aria-label="Permalink to “ERB 的表达式”">​</a></h1><p>表达式是“能算出结果的东西”。本页汇总 EraBasic 表达式的组成元素与规则。更详细的说明请参阅<a href="./../translation/Operator.html">运算</a>与<a href="./../translation/General.html">常规</a>。</p><h2 id="字面量" tabindex="-1">字面量 <a class="header-anchor" href="#字面量" aria-label="Permalink to “字面量”">​</a></h2><table tabindex="0"><thead><tr><th>种类</th><th>写法</th><th>例子</th></tr></thead><tbody><tr><td>十进制整数</td><td>直接书写</td><td><code>123</code>、<code>-5</code></td></tr><tr><td>十六进制整数</td><td><code>0x</code> 开头</td><td><code>0xFF</code></td></tr><tr><td>二进制整数</td><td><code>0b</code> 开头</td><td><code>0b1010</code></td></tr><tr><td>字符串</td><td>双引号包围</td><td><code>&quot;Hello&quot;</code></td></tr><tr><td>格式化字符串</td><td><code>@&quot;...&quot;</code></td><td><code>@&quot;{A} 点&quot;</code></td></tr><tr><td>文本（命令参数）</td><td>不加引号</td><td><code>PRINT Hello</code></td></tr></tbody></table><blockquote><p>数值是 <strong>64 位有符号整数</strong>，没有小数。<code>5 / 3</code> 的结果是 <code>1</code>。</p></blockquote><h2 id="运算符与优先级" tabindex="-1">运算符与优先级 <a class="header-anchor" href="#运算符与优先级" aria-label="Permalink to “运算符与优先级”">​</a></h2><p>从高到低：</p><table tabindex="0"><thead><tr><th>分类</th><th>优先级</th><th>符号</th></tr></thead><tbody><tr><td>单目运算符</td><td>高</td><td><code>~</code>、<code>!</code>、<code>-</code>（负号）</td></tr><tr><td>算术运算符</td><td>↑</td><td><code>*</code>、<code>/</code>、<code>%</code></td></tr><tr><td></td><td></td><td><code>+</code>、<code>-</code></td></tr><tr><td>位移运算符</td><td></td><td><code>&lt;&lt;</code>、<code>&gt;&gt;</code></td></tr><tr><td>比较运算符</td><td></td><td><code>&lt;</code>、<code>&gt;</code>、<code>&lt;=</code>、<code>&gt;=</code>、<code>==</code>、<code>!=</code></td></tr><tr><td>位运算符</td><td></td><td><code>&amp;</code>、\`</td></tr><tr><td>逻辑运算符</td><td>↓</td><td><code>&amp;&amp;</code>、\`</td></tr><tr><td>三元运算符</td><td>低</td><td><code>? … #</code></td></tr><tr><td>赋值运算符</td><td>最低</td><td><code>=</code>、<code>+=</code>、<code>-=</code>、<code>*=</code>、<code>/=</code>、<code>%=</code>、<code>&#39;=</code></td></tr></tbody></table><h3 id="算术" tabindex="-1">算术 <a class="header-anchor" href="#算术" aria-label="Permalink to “算术”">​</a></h3><table tabindex="0"><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td><code>+</code></td><td>加法（字符串则为拼接）</td></tr><tr><td><code>-</code></td><td>减法</td></tr><tr><td><code>*</code></td><td>乘法（字符串 <code>*</code> 整数为重复）</td></tr><tr><td><code>/</code></td><td>整除</td></tr><tr><td><code>%</code></td><td>取余</td></tr></tbody></table><h3 id="比较与逻辑" tabindex="-1">比较与逻辑 <a class="header-anchor" href="#比较与逻辑" aria-label="Permalink to “比较与逻辑”">​</a></h3><table tabindex="0"><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td><code>==</code> / <code>!=</code></td><td>等于 / 不等于</td></tr><tr><td><code>&lt;</code> / <code>&gt;</code> / <code>&lt;=</code> / <code>&gt;=</code></td><td>大小比较</td></tr><tr><td><code>&amp;&amp;</code> / \`</td><td></td></tr><tr><td><code>!</code></td><td>逻辑非</td></tr><tr><td><code>^^</code> / <code>!&amp;</code> / \`!</td><td>\`</td></tr></tbody></table><p>比较结果为 <code>1</code>（真）或 <code>0</code>（假）。<code>&amp;&amp;</code> 与 <code>||</code> 会<strong>短路求值</strong>：<code>A &amp;&amp; B</code> 中若 <code>A</code> 为假则不再计算 <code>B</code>。</p><h2 id="三元运算符" tabindex="-1">三元运算符 <a class="header-anchor" href="#三元运算符" aria-label="Permalink to “三元运算符”">​</a></h2><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#9CDCFE;">变量</span><span style="color:#D4D4D4;"> =</span><span style="color:#9CDCFE;"> 条件</span><span style="color:#D4D4D4;"> ?</span><span style="color:#9CDCFE;"> 为真时的值</span><span style="color:#D4D4D4;"> #</span><span style="color:#9CDCFE;"> 为假时的值</span></span></code></pre></div><p>字符串版本需要外层 <code>\\@ … \\@</code>：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#9CDCFE;">变量</span><span style="color:#D4D4D4;"> =</span><span style="color:#569CD6;"> \\@</span><span style="color:#9CDCFE;">条件</span><span style="color:#D4D4D4;"> ? 为真时的文本 # 为假时的文本</span><span style="color:#569CD6;">\\@</span></span></code></pre></div><p>它等价于：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#C586C0;">IF</span><span style="color:#9CDCFE;"> 条件</span></span>
<span class="line"><span style="color:#9CDCFE;">  变量</span><span style="color:#D4D4D4;"> =</span><span style="color:#9CDCFE;"> 为真时的值</span></span>
<span class="line"><span style="color:#C586C0;">ELSE</span></span>
<span class="line"><span style="color:#9CDCFE;">  变量</span><span style="color:#D4D4D4;"> =</span><span style="color:#9CDCFE;"> 为假时的值</span></span>
<span class="line"><span style="color:#C586C0;">ENDIF</span></span></code></pre></div><h2 id="form-语法" tabindex="-1">FORM 语法 <a class="header-anchor" href="#form-语法" aria-label="Permalink to “FORM 语法”">​</a></h2><p>在 <code>PRINTFORM</code> 等命令中，可以嵌入表达式，并按指定宽度对齐：</p><ul><li><code>{数值表达式}</code>：展开为数值；</li><li><code>{数值表达式, 宽度, LEFT/RIGHT}</code>：按宽度对齐；</li><li><code>%字符串表达式%</code>：展开为字符串；</li><li><code>%字符串表达式, 宽度, LEFT/RIGHT%</code>：按宽度对齐。</li></ul><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#569CD6;">PRINTFORM</span><span style="color:#E6E6E6;"> 金币：</span><span style="color:#569CD6;">{</span><span style="color:#9CDCFE;">MONEY</span><span style="color:#569CD6;">}</span></span>
<span class="line"><span style="color:#569CD6;">PRINTFORM</span><span style="color:#E6E6E6;"> 姓名：</span><span style="color:#569CD6;">%</span><span style="color:#9CDCFE;">NAME</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#569CD6;">%</span></span>
<span class="line"><span style="color:#569CD6;">PRINTFORM</span><span style="color:#E6E6E6;"> [</span><span style="color:#569CD6;">{</span><span style="color:#9CDCFE;">MONEY</span><span style="color:#D4D4D4;">,</span><span style="color:#B5CEA8;">10</span><span style="color:#D4D4D4;">,</span><span style="color:#9CDCFE;">LEFT</span><span style="color:#569CD6;">}</span><span style="color:#E6E6E6;">]</span></span></code></pre></div><p>三连符号（<code>***</code>、<code>$$$</code>、<code>+++</code>、<code>///</code>、<code>===</code>）用于替换角色姓名等，详见 <a href="./CSV_File.html#str-csv">Str.csv</a>。</p><h2 id="式中函数" tabindex="-1">式中函数 <a class="header-anchor" href="#式中函数" aria-label="Permalink to “式中函数”">​</a></h2><p>表达式里可以调用<strong>式中函数</strong>，它们像普通函数一样接收参数、返回结果：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#9CDCFE;">A</span><span style="color:#D4D4D4;"> =</span><span style="color:#DCDCAA;"> ABS</span><span style="color:#E6E6E6;">(</span><span style="color:#9CDCFE;">X</span><span style="color:#E6E6E6;">)</span></span>
<span class="line"><span style="color:#9CDCFE;">B</span><span style="color:#D4D4D4;"> =</span><span style="color:#DCDCAA;"> STRLEN</span><span style="color:#E6E6E6;">(</span><span style="color:#9CDCFE;">S</span><span style="color:#E6E6E6;">)</span></span>
<span class="line"><span style="color:#9CDCFE;">C</span><span style="color:#D4D4D4;"> =</span><span style="color:#DCDCAA;"> RAND</span><span style="color:#E6E6E6;">(</span><span style="color:#B5CEA8;">100</span><span style="color:#E6E6E6;">)</span></span>
<span class="line"><span style="color:#9CDCFE;">D</span><span style="color:#D4D4D4;"> =</span><span style="color:#DCDCAA;"> SUBSTRING</span><span style="color:#E6E6E6;">(</span><span style="color:#9CDCFE;">S</span><span style="color:#E6E6E6;">, </span><span style="color:#B5CEA8;">1</span><span style="color:#E6E6E6;">, </span><span style="color:#B5CEA8;">3</span><span style="color:#E6E6E6;">)</span></span></code></pre></div><p>内置式中函数的完整清单见<a href="./../translation/Expression.html">表达式内函数</a>。</p><h2 id="类型与转换" tabindex="-1">类型与转换 <a class="header-anchor" href="#类型与转换" aria-label="Permalink to “类型与转换”">​</a></h2><ul><li>数值与字符串<strong>不会自动转换</strong>：想拼接数字和文本，需要用 <code>TOSTR</code> / <code>TOINT</code>；</li><li>常见转换函数：<code>TOSTR</code>（数值→字符串）、<code>TOINT</code>（字符串→数值）、<code>ISNUMERIC</code>（判断能否转数值）。</li></ul><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DimS</span><span style="color:#9CDCFE;"> Msg</span><span style="color:#D4D4D4;"> =</span><span style="color:#CE9178;"> &quot;金币：&quot;</span></span>
<span class="line"><span style="color:#9CDCFE;">Msg</span><span style="color:#D4D4D4;"> =</span><span style="color:#9CDCFE;"> Msg</span><span style="color:#D4D4D4;"> +</span><span style="color:#DCDCAA;"> TOSTR</span><span style="color:#E6E6E6;">(</span><span style="color:#9CDCFE;">MONEY</span><span style="color:#E6E6E6;">)</span></span></code></pre></div><h2 id="括号" tabindex="-1">括号 <a class="header-anchor" href="#括号" aria-label="Permalink to “括号”">​</a></h2><p>拿不准优先级时，<strong>永远加括号</strong>。括号内的内容总会被最先计算：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#9CDCFE;">A</span><span style="color:#D4D4D4;"> +</span><span style="color:#9CDCFE;"> B</span><span style="color:#D4D4D4;"> *</span><span style="color:#B5CEA8;"> 2</span><span style="color:#6A9955;">    ; 先乘后加</span></span>
<span class="line"><span style="color:#E6E6E6;">(</span><span style="color:#9CDCFE;">A</span><span style="color:#D4D4D4;"> +</span><span style="color:#9CDCFE;"> B</span><span style="color:#E6E6E6;">) </span><span style="color:#D4D4D4;">*</span><span style="color:#B5CEA8;"> 2</span><span style="color:#6A9955;">  ; 先加后乘</span></span></code></pre></div><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to “相关链接”">​</a></h2><ul><li><a href="./../translation/Operator.html">运算</a></li><li><a href="./../translation/General.html">常规</a></li><li><a href="./../translation/Expression.html">表达式内函数</a></li><li><a href="./ERB_Statements.html">ERB 的语句</a></li></ul>`,36)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};